'use strict';
const deliveryNext={Assigned:'Accepted',Accepted:'Picked up','Picked up':'Out for delivery','Out for delivery':'Delivered'};
const deliverySummary=o=>{const a=o.deliveryAssignment;if(!a)return '';const status=o.status==='Cancelled'?'Cancelled':a.status,closed=['Cancelled','Delivery failed','Returned to seller'].includes(status);return '<div class="notice"><b>Delivery: '+esc(status)+'</b><br>'+(status==='Cancelled'?'Previously assigned rider: ':'Rider: ')+esc(a.riderName)+(closed?'<br>No delivery is scheduled.':'<br>Estimated arrival: '+esc(a.estimatedDate||'To be confirmed'))+(status==='Delivery failed'?'<br>Reason: '+esc(a.failureReason||'Contact your seller')+'<br>Your seller will arrange the next step.':'')+'</div>';};
function deliveryJobCard(j){
 if(j.status==='Reassigned')return '<article class="panel section"><h2>'+esc(j.orderId)+'</h2><span class="status">Reassigned</span><p>This job is now assigned to another rider. Do not collect or deliver this parcel.</p></article>';
 const inactive=['Cancelled','Delivery failed','Returned to seller'].includes(j.status),failure=['Accepted','Picked up','Out for delivery'].includes(j.status);
 return '<article class="panel section"><h2>'+esc(j.orderId)+'</h2><span class="status">'+esc(j.status)+'</span><p>'+esc(j.destination)+'</p>'+(inactive?'<p>No delivery is scheduled.</p>':'<p>Estimated arrival: '+esc(j.estimatedDate||'To be confirmed')+'</p>')+'<p>Recipient phone: <a href="tel:'+esc(j.recipient?.phone||'')+'">'+esc(j.recipient?.phone||'Contact seller')+'</a></p><p>'+(j.status==='Cancelled'?'Cancelled — no payment collected':j.status==='Returned to seller'?'Parcel returned — payment not collected':(j.status==='Delivered'?'Cash collected — awaiting settlement':'Pay on delivery')+': <b>'+money(j.total)+'</b>')+'</p>'+(j.status==='Delivery failed'?'<div class="notice">Reason: '+esc(j.failureReason)+'. '+(j.failedFrom==='Accepted'?'The seller still has the parcel.':'Keep custody of the parcel and contact the seller to arrange a retry or physical return.')+'</div>':'')+(j.lines||[]).map(l=>'<p>'+esc(l.name)+' · '+esc(l.variant)+' × '+l.qty+'</p>').join('')+(deliveryNext[j.status]?'<button class="primary" data-delivery-next="'+esc(deliveryNext[j.status])+'" data-id="'+esc(j.id)+'">'+(j.status==='Assigned'?'Accept job':'Record '+esc(deliveryNext[j.status]).toLowerCase())+'</button>':'')+(failure?' <button class="secondary" data-delivery-fail="'+esc(j.id)+'">Report delivery problem</button>':'')+'</article>';
}
function courierPage(){
 const c=KstoreCloud;if(!state.user)return login();
 if(!c.auth?.emailVerified)return '<section class="panel empty"><h1>Verify your email before applying to deliver</h1><p>Check your inbox and spam folder, then refresh your verification status.</p><button class="primary" data-firebase-action="verify">Send verification email</button> <button class="secondary" data-firebase-action="refresh-auth">I have verified my email</button></section>';
 if(!c.courierProfile?.active)return '<section class="panel" style="max-width:600px;margin:30px auto"><h1>Join the Kstore delivery team</h1><p>Verified accounts can apply. A platform operator must approve you before you receive customer delivery details.</p>'+(c.courierProfile?'<div class="notice">Application: '+esc(c.courierProfile.status)+'</div>':'')+'<form id="courier-application"><label class="field">Rider name<input name="name" required maxlength="70" value="'+esc(c.courierProfile?.name||state.user.name)+'"></label><label class="field">Contact phone<input name="phone" required pattern="[0-9+ ()-]{9,20}" value="'+esc(c.courierProfile?.phone||'')+'"></label><button class="primary">Save rider application</button></form></section>';
 return '<h1>Your delivery jobs</h1><p class="muted">Record each step after it happens. Cash collection is recorded separately from settlement.</p>'+(c.courierError?'<p class="error">'+esc(c.courierError)+'</p>':'')+((c.courierJobs||[]).length?c.courierJobs.map(deliveryJobCard).join(''):'<div class="panel empty"><h2>No assigned jobs</h2><p>New assignments will appear here.</p></div>');
}
const deliveryOriginalRender=render;render=function(){if(KstoreCloud.enabled&&KstoreCloud.ready&&KstoreCloud.catalogReady&&['/courier','/rider'].includes(route().path)){$('#app').innerHTML=header()+'<main class="wrap">'+courierPage()+'</main>'+footer();document.title='Delivery team | Kstore';return;}deliveryOriginalRender();};
const deliveryOriginalFooter=footer;footer=function(){const html=deliveryOriginalFooter().replace('Interactive demo · Purchases and payments are simulated · Data is saved in this browser','Account connected · Online payments are not available');return KstoreCloud.enabled?html.replace('<div class="footer-bottom">','<div style="display:flex;flex-wrap:wrap;gap:14px;padding:16px 0"><a href="#/courier">Kstore delivery team</a><a href="tel:0543496314">0543496314</a><a href="mailto:support@kstore.com">support@kstore.com</a></div><div class="footer-bottom">'):html;};
const deliveryOriginalInfo=infoPage;infoPage=function(id){if(!KstoreCloud.enabled)return deliveryOriginalInfo(id);if(id==='privacy')return deliveryOriginalInfo(id).replace('</section>','<p>Your recipient name, phone and delivery address are shared with your seller and assigned approved rider to fulfil your order.</p></section>');if(id==='contact')return '<section class="panel legal"><h1>Contact Kstore</h1><p>Phone: <a href="tel:0543496314">0543496314</a></p><p>Email: <a href="mailto:support@kstore.com">support@kstore.com</a></p><p>Include your order number when asking about an order.</p></section>';if(id==='shipping')return '<section class="panel legal"><h1>Delivery & tracking</h1><p>Door delivery costs GH₵45 within the configured Greater Accra pilot service area, including Kasoa. Pickup is not available yet.</p><p>Our pilot target is 1–2 business days after confirmed dispatch. Your assigned delivery date is confirmed when a rider is assigned; this is an estimate.</p><p>Track assignment, pickup and delivery progress in your account’s order details. Payment is due on delivery. Contact <a href="tel:0543496314">0543496314</a> for delivery questions.</p></section>';return deliveryOriginalInfo(id);};
const deliveryOriginalSellerRow=sellerOrderRow;sellerOrderRow=function(o){let html=deliveryOriginalSellerRow(o);if(!KstoreCloud.enabled)return html;const a=o.deliveryAssignment;if(sellerOrderStatus(o)==='Packed'){html=html.replace(/<button[^>]*data-seller="order-status"[^>]*data-value="Shipped"[^>]*>[\s\S]*?<\/button>/g,'');if(!a||['Assigned','Accepted','Delivery failed','Returned to seller'].includes(a.status))html+='<button class="primary" data-delivery-assign="'+esc(o.id)+'">'+(a?'Reassign rider':'Assign rider')+'</button>';}if(a?.status==='Delivery failed'&&['Packed','Shipped'].includes(o.status)){html+='<button class="secondary" data-delivery-resolve="retry" data-id="'+esc(o.id)+'">Arrange retry with same rider</button>';if(o.status==='Shipped')html+=' <button class="secondary" data-delivery-resolve="returned" data-id="'+esc(o.id)+'">Confirm parcel returned</button>';}return html+deliverySummary(o);};
const deliveryOriginalDetail=orderDetail;orderDetail=function(o){deliveryOriginalDetail(o);if(KstoreCloud.enabled)$('#modal').insertAdjacentHTML('beforeend',deliverySummary(o));};
let deliveryBusy=false;
async function deliveryRun(button,work){if(deliveryBusy)return;deliveryBusy=true;if(button)button.disabled=true;try{await KstoreCloud.ensureVerified();await work();}catch(e){toast(e.message||'Delivery action failed.');}finally{deliveryBusy=false;if(button?.isConnected)button.disabled=false;}}
window.addEventListener('click',event=>{
 if(!KstoreCloud.enabled)return;
 const assign=event.target.closest('[data-delivery-assign]');if(assign){event.preventDefault();event.stopImmediatePropagation();return deliveryRun(assign,async()=>{const o=state.orders.find(x=>x.id===assign.dataset.deliveryAssign),prior=o?.deliveryAssignment,riders=(await KstoreCloud.loadCouriers()).filter(r=>r.id!==prior?.courierUid);modal(prior?'Reassign delivery rider':'Assign delivery rider',riders.length?'<form id="delivery-assignment"><input type="hidden" name="id" value="'+esc(assign.dataset.deliveryAssign)+'">'+(prior?'<input type="hidden" name="expectedCourierUid" value="'+esc(prior.courierUid)+'"><label class="field">Reason for reassignment<input name="reason" required minlength="5" maxlength="200"></label><p>The parcel must be with the seller before another rider is assigned.</p>':'')+'<label class="field">Approved rider<select name="courierUid">'+riders.map(r=>'<option value="'+esc(r.id)+'">'+esc(r.name)+'</option>').join('')+'</select></label><label class="field">Estimated arrival date<input type="date" name="estimatedDate" min="'+new Date().toISOString().slice(0,10)+'" required></label><p class="muted">Confirm this date with your rider. Pilot target: 1–2 business days after dispatch.</p><button class="primary">'+(prior?'Reassign rider':'Assign rider')+'</button></form>':'<p>No other approved riders are available. A rider must apply through the Delivery team page and be approved by the platform operator.</p>');});}
 const failed=event.target.closest('[data-delivery-fail]');if(failed){event.preventDefault();event.stopImmediatePropagation();return modal('Report delivery problem','<form id="delivery-failure"><input type="hidden" name="id" value="'+esc(failed.dataset.deliveryFail)+'"><label class="field">Reason<select name="reason">'+['Recipient unavailable','Address issue','Recipient declined','Vehicle issue','Other'].map(x=>'<option>'+x+'</option>').join('')+'</select></label><p>This pauses delivery. It does not cancel the order, collect cash or restore stock. If you have the parcel, keep it safe and contact the seller to arrange a retry or physical return.</p><button class="primary">Report problem</button></form>');}
 const resolve=event.target.closest('[data-delivery-resolve]');if(resolve){event.preventDefault();event.stopImmediatePropagation();const o=state.orders.find(x=>x.id===resolve.dataset.id);if(!o?.deliveryAssignment)return;return modal(resolve.dataset.deliveryResolve==='retry'?'Arrange delivery retry':'Confirm parcel return','<form id="delivery-resolution"><input type="hidden" name="id" value="'+esc(o.id)+'"><input type="hidden" name="expectedCourierUid" value="'+esc(o.deliveryAssignment.courierUid)+'"><input type="hidden" name="action" value="'+esc(resolve.dataset.deliveryResolve)+'">'+(resolve.dataset.deliveryResolve==='retry'?'<label class="field">New estimated arrival<input type="date" name="estimatedDate" required min="'+new Date().toISOString().slice(0,10)+'"></label><p>Confirm the retry date with the same rider. This does not transfer the parcel to another rider.</p>':'<label><input type="checkbox" name="parcelReceived" required> I have physically received the parcel back from the rider.</label><p>This makes the packed parcel available for reassignment. It does not restore inventory or mark payment collected.</p>')+'<button class="primary">Confirm</button></form>');}
 const next=event.target.closest('[data-delivery-next]');if(next){event.preventDefault();event.stopImmediatePropagation();return deliveryRun(next,async()=>{if(next.dataset.deliveryNext==='Delivered'){const job=KstoreCloud.courierJobs.find(j=>j.id===next.dataset.id);modal('Confirm delivery & cash collection','<form id="delivery-completion"><input type="hidden" name="id" value="'+esc(job.id)+'"><label class="field">Received by<input name="receivedBy" required maxlength="70"></label><label><input type="checkbox" name="cashCollected" required> I collected the full '+money(job.total)+' cash payment.</label><p>This records collection; it does not settle funds to the seller.</p><button class="primary">Confirm delivered</button></form>');}else await KstoreCloud.call('updateCourierDelivery',{id:next.dataset.id,status:next.dataset.deliveryNext});});}
 const slip=event.target.closest('[data-seller="packing-slip"]');if(slip){event.preventDefault();event.stopImmediatePropagation();const o=state.orders.find(x=>x.id===slip.dataset.id);if(!o)return;return sellerDownload('packing-slip-'+o.id+'.txt','KSTORE PACKING SLIP\nOrder: '+o.id+'\nStore: '+state.seller.shopName+'\nDestination: '+o.destination+'\nRecipient phone: '+(o.recipient?.phone||'Contact must be confirmed for this older order')+'\n\n'+sellerOrderLines(o).map(l=>l.name+' | '+l.variant+' | Qty '+l.qty).join('\n')+'\n\nThis is a packing slip, not a carrier booking.\nSupport: 0543496314 | support@kstore.com','text/plain');}
},true);
window.addEventListener('submit',event=>{if(!KstoreCloud.enabled||!['courier-application','delivery-assignment','delivery-completion','delivery-failure','delivery-resolution'].includes(event.target.getAttribute('id')))return;event.preventDefault();event.stopImmediatePropagation();const form=event.target,d=Object.fromEntries(new FormData(form)),id=form.getAttribute('id');deliveryRun(form.querySelector('button'),async()=>{if(id==='courier-application'){await KstoreCloud.call('requestCourierAccess',d);render();toast('Rider application saved for review.');return;}if(id==='delivery-assignment')await KstoreCloud.call('assignDelivery',d);else if(id==='delivery-failure')await KstoreCloud.call('updateCourierDelivery',{...d,status:'Delivery failed'});else if(id==='delivery-resolution')await KstoreCloud.call('resolveDeliveryFailure',{...d,parcelReceived:d.parcelReceived==='on'});else await KstoreCloud.call('updateCourierDelivery',{...d,status:'Delivered',cashCollected:d.cashCollected==='on'});$('#modal').close();render();toast(id==='delivery-assignment'?'Rider assigned.':id==='delivery-failure'?'Delivery problem recorded.':id==='delivery-resolution'?'Delivery updated.':'Delivery and cash collection recorded.');});},true);
